import { useEffect, useState } from 'react';

export function useWindowWidth() {
  const [width, setWidth] = useState(() => window.innerWidth);

  useEffect(() => {
    const onResize = () => setWidth(window.innerWidth);
    window.addEventListener('resize', onResize);
    return () => window.removeEventListener('resize', onResize);
  }, []);

  return width;
}

import { useWindowWidth } from './useWindowWidth.js';

function Layout() {
  const width = useWindowWidth();
  return <p>{width < 768 ? 'Mobile layout' : 'Desktop layout'} ({width}px)</p>;
}

import { useState } from 'react';

export function useCounter(initial = 0, step = 1) {
  const [count, setCount] = useState(initial);
  const increment = () => setCount((c) => c + step);
  const reset = () => setCount(initial);
  return { count, increment, reset };
}

import { useCounter } from './useCounter.js';

function Scoreboard() {
  const home = useCounter(0, 1);
  const away = useCounter(0, 3);

  return (
    <>
      <button onClick={home.increment}>Home: {home.count}</button>
      <button onClick={away.increment}>Away: {away.count}</button>
      <button onClick={() => { home.reset(); away.reset(); }}>Reset</button>
    </>
  );
}

import { useEffect, useState } from 'react';

export function useLocalStorage(key, initialValue) {
  const [value, setValue] = useState(() => {
    const stored = localStorage.getItem(key);
    return stored === null ? initialValue : JSON.parse(stored);
  });

  useEffect(() => {
    localStorage.setItem(key, JSON.stringify(value));
  }, [key, value]);

  return [value, setValue];
}

import { useLocalStorage } from './useLocalStorage.js';

function Settings() {
  const [fontSize, setFontSize] = useLocalStorage('fontSize', 16);

  return (
    <label>
      Font size: {fontSize}px
      <input
        type="range" min="12" max="24" value={fontSize}
        onChange={(e) => setFontSize(Number(e.target.value))}
      />
    </label>
  );
}

import { useEffect, useState } from 'react';

export function useFetch(url) {
  const [state, setState] = useState({ status: 'loading', data: null, error: null });

  useEffect(() => {
    let ignore = false;
    setState({ status: 'loading', data: null, error: null });

    fetch(url)
      .then((res) => {
        if (!res.ok) throw new Error(`HTTP ${res.status}`);
        return res.json();
      })
      .then((data) => {
        if (!ignore) setState({ status: 'ready', data, error: null });
      })
      .catch((error) => {
        if (!ignore) setState({ status: 'error', data: null, error });
      });

    return () => {
      ignore = true;
    };
  }, [url]);

  return state;
}

import { useFetch } from './useFetch.js';

function Todo({ id }) {
  const { status, data, error } = useFetch(`https://jsonplaceholder.typicode.com/todos/${id}`);

  if (status === 'loading') return <p>Loading…</p>;
  if (status === 'error') return <p>Error: {error.message}</p>;
  return <p>{data.title}</p>;
}
